def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge them
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Disjoint, add as new interval
                merged.append([start, end])

        return merged

    # Merge intervals in both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    result = []

    for a_start, a_end in a_merged:
        current = [[a_start, a_end]]

        # Subtract each interval in b from current
        for b_start, b_end in b_merged:
            next_current = []

            for c_start, c_end in current:
                if b_end <= c_start or b_start >= c_end:
                    # No overlap
                    next_current.append([c_start, c_end])
                else:
                    # There is overlap, keep the non-overlapping parts
                    if c_start < b_start:
                        next_current.append([c_start, b_start])
                    if b_end < c_end:
                        next_current.append([b_end, c_end])

            current = next_current

        result.extend(current)

    return result

